"use client";

import type { ReactNode } from "react";
import { CssBaseline, ThemeProvider } from "@mui/material";
import { easyPrintTheme } from "./easyprint-theme";

export function EasyPrintThemeProvider({ children }: { children: ReactNode }) {
  return (
    <ThemeProvider theme={easyPrintTheme}>
      <CssBaseline />
      {children}
    </ThemeProvider>
  );
}
